<script setup lang="ts">
const { show: showGlobalToast } = useAdminToast()
import { ChevronDown, ChevronUp, Plus, RotateCcw, Trash2 } from 'lucide-vue-next'
type Slot='featured'|'supporting'|'explore';type HeroTopic={id:string;label:string;isActive:boolean;sortOrder:number};const canonicalTopics=['Rekomendasi Kuliner','Tren Sosial','Transportasi Publik','Literasi Ibadah','Kondisi Harian','Kultur Lokal','Tips Jamaah','Panduan Umrah','Fasilitas Umum','Sudut Madinah','Rute & Navigasi','Etika Masjid','Biaya Harian','Tempat Favorit','Info Musiman','Keseharian Saudi'];const articles=ref<any[]>([]),featured=ref<number|null>(null),supporting=ref<number[]>([]),explore=ref<number[]>([]),hero=reactive({imageUrl:'',imageFileId:'',headline:'',subheadline:''}),heroTopics=ref<HeroTopic[]|null>(null),newTopic=ref(''),picker=ref<any>(null),search=ref(''),preview=ref(false),resetAllConfirm=ref(false),device=ref<'desktop'|'mobile'>('desktop'),pending=ref(true),saving=ref(false),dirty=ref(false),toast=ref(''),error=ref('');const topicRows=computed(()=>heroTopics.value===null?canonicalTopics.map((label,i)=>({id:'default-'+i,label,isActive:true,sortOrder:i*10})):heroTopics.value);const topicPageSize=8;const topicPageNumber=ref(1);const topicPageCount=computed(()=>Math.max(1,Math.ceil(topicRows.value.length/topicPageSize)));const topicPage=computed(()=>topicRows.value.map((topic,index)=>({topic,index})).slice((topicPageNumber.value-1)*topicPageSize,topicPageNumber.value*topicPageSize));const previewTopics=computed(()=>topicRows.value.filter(x=>x.isActive).sort((a,b)=>a.sortOrder-b.sortOrder).map(x=>x.label));const available=computed(()=>articles.value.filter(a=>a.status==='PUBLISHED'&&(!search.value||a.title.toLowerCase().includes(search.value.toLowerCase()))));const pickList=computed(()=>picker.value==='supporting'?supporting.value:explore.value);function item(id:number){return articles.value.find(a=>a.id===id)}function mark(){dirty.value=true}function ensureTopics(){if(heroTopics.value===null)heroTopics.value=canonicalTopics.map((label,i)=>({id:'default-'+i,label,isActive:true,sortOrder:i*10}))}function editTopic(i:number,value:string){ensureTopics();if(heroTopics.value)heroTopics.value[i].label=value.trimStart();mark()}function addTopic(){const label=newTopic.value.trim();if(!label||heroTopics.value?.some(x=>x.label.toLowerCase()===label.toLowerCase()))return;if(heroTopics.value===null)heroTopics.value=canonicalTopics.map((x,i)=>({id:'default-'+i,label:x,isActive:true,sortOrder:i*10}));heroTopics.value.push({id:'topic-'+Date.now(),label,isActive:true,sortOrder:heroTopics.value.length*10});newTopic.value='';mark()}function removeTopic(i:number){heroTopics.value?.splice(i,1);mark()}function toggleTopic(i:number){if(heroTopics.value)heroTopics.value[i].isActive=!heroTopics.value[i].isActive;mark()}function moveTopic(i:number,d:number){if(!heroTopics.value)return;const j=i+d;if(j<0||j>=heroTopics.value.length)return;[heroTopics.value[i],heroTopics.value[j]]=[heroTopics.value[j],heroTopics.value[i]];heroTopics.value.forEach((x,n)=>x.sortOrder=n*10);mark()}function resetTopics(){heroTopics.value=null;topicPageNumber.value=1;mark()}function setTopicPage(page:number){topicPageNumber.value=Math.min(Math.max(page,1),topicPageCount.value)}watch(topicPageCount,()=>setTopicPage(topicPageNumber.value));function add(id:number){if(!picker.value)return;const target=pickList.value;if(!target.includes(id)&&(picker.value==='supporting'?target.length<3:target.length<6)){target.push(id);mark()}picker.value=null}function remove(slot:Slot,id:number){if(slot==='featured')featured.value=null;else{const target=slot==='supporting'?supporting.value:explore.value;const i=target.indexOf(id);if(i>=0)target.splice(i,1)}mark()}function move(slot:'supporting'|'explore',i:number,d:number){const target=slot==='supporting'?supporting.value:explore.value;const j=i+d;if(j<0||j>=target.length)return;[target[i],target[j]]=[target[j],target[i]];mark()}
async function load(){try{const [a,s]=await Promise.all([$fetch<any>('/api/admin/media/articles',{query:{status:'PUBLISHED',page:1,pageSize:50}}),$fetch<any>('/api/admin/media/page-settings/home')]);articles.value=a.data;const x=s.data||{};featured.value=x.featuredArticleId??null;supporting.value=[...(x.supportingArticleIds||[])];explore.value=[...(x.editorialArticleIds||[])];Object.assign(hero,{imageUrl:x.heroImageUrl||'',imageFileId:x.heroImageFileId||'',headline:x.heroHeadline||'',subheadline:x.heroSubheadline||''});heroTopics.value=x.heroTopicOverride===null||x.heroTopicOverride===undefined?null:JSON.parse(JSON.stringify(x.heroTopicOverride))}catch(e:any){error.value=e.data?.statusMessage||'Settings gagal dimuat.'}finally{pending.value=false}}async function save(){saving.value=true;error.value='';try{await $fetch('/api/admin/media/page-settings/home',{method:'PATCH',body:{...hero,heroImageFileId:hero.imageFileId||null,heroImageUrl:hero.imageUrl||null,heroHeadline:hero.headline||null,heroSubheadline:hero.subheadline||null,heroTopicOverride:heroTopics.value,featuredArticleId:featured.value,supportingArticleIds:supporting.value,editorialArticleIds:explore.value}});dirty.value=false;showGlobalToast('Pengaturan Home berhasil disimpan.','success')}catch(e:any){error.value=e.data?.statusMessage||'Settings gagal disimpan.'}finally{saving.value=false}}function resetHeroField(field:'headline'|'subheadline'|'image'){if(field==='headline')hero.headline='';if(field==='subheadline')hero.subheadline='';if(field==='image'){hero.imageUrl='';hero.imageFileId=''}mark()}function resetSpotlight(){featured.value=null;supporting.value=[];mark()}function resetAll(){resetHeroField('headline');resetHeroField('subheadline');resetHeroField('image');resetSpotlight();explore.value=[];resetTopics();mark()}function title(id:number|null){return id?item(id)?.title||'Artikel tidak lagi terbit':'Otomatis berdasarkan artikel terbit'}onMounted(load)
</script>
<template><div><PageHead title="Settings · Home" subtitle="Media · Page Settings"><template #actions><span v-if="dirty" class="rounded-full border border-gold-soft bg-gold-sand px-3 py-1.5 text-xs font-semibold">Perubahan belum disimpan</span><button class="rounded-full border border-neutral-line px-4 py-2 text-sm font-semibold" @click="preview=true">Preview</button></template></PageHead><p v-if="error" class="mt-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-800">{{error}}</p><div v-if="pending" class="mt-8 rounded-2xl border bg-white p-8 text-sm">Memuat pengaturan Home...</div><div v-else class="mt-8 space-y-5"><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">1. Hero</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Editable · hanya konten editorial, template tetap dikelola sh-web.</p></div><span class="rounded-full bg-gold-sand px-3 py-1 text-[10px] font-semibold uppercase">Editable</span></div><div class="mt-3 flex flex-wrap gap-2"><button class="text-xs underline" @click="resetHeroField('headline')">Reset headline</button><button class="text-xs underline" @click="resetHeroField('subheadline')">Reset subheadline</button><button class="text-xs underline" @click="resetHeroField('image')">Reset image</button><button class="text-xs text-red-700 underline" @click="resetHeroField('headline');resetHeroField('subheadline');resetHeroField('image')">Reset Hero</button></div><div class="mt-5 grid gap-4 lg:grid-cols-[240px_1fr]"><MediaImageUploader v-model="hero.imageUrl" @update:file-id="hero.imageFileId=$event;mark()" label="Background / banner image" folder="home"/><div class="space-y-3"><label class="block text-sm font-semibold">Headline<input v-model="hero.headline" class="mt-1 w-full rounded-xl border px-3 py-2 text-sm" placeholder="Headline hero" @input="mark"/></label><label class="block text-sm font-semibold">Subheadline<textarea v-model="hero.subheadline" rows="3" class="mt-1 w-full rounded-xl border px-3 py-2 text-sm" placeholder="Subheadline hero" @input="mark"/></label></div></div><div class="mt-5 rounded-xl border border-neutral-line bg-neutral-soft/40 p-4"><div class="flex items-center justify-between gap-3"><div><h3 class="font-semibold">Topik Hero</h3><p class="mt-1 text-xs text-neutral-charcoal/55">Override opsional. Tanpa override, memakai daftar default sh-web.</p></div><button type="button" class="inline-flex items-center gap-1 text-xs text-red-700 underline" title="Reset topik ke default" @click="resetTopics"><RotateCcw class="h-3.5 w-3.5"/>Reset Topik ke Default</button></div><div class="mt-3 flex gap-2"><input v-model="newTopic" class="min-h-[38px] flex-1 rounded-lg border px-3 text-sm" placeholder="Tambah topik" @keyup.enter="addTopic"/><button type="button" class="inline-flex items-center gap-1 rounded-full bg-brand-green px-3 py-2 text-xs font-semibold text-white" @click="addTopic"><Plus class="h-4 w-4"/>Tambah Topik</button></div><div class="mt-3 space-y-2"><div v-for="entry in topicPage" :key="entry.topic.id" class="flex min-w-0 items-center gap-2 rounded-lg border bg-white p-2"><button type="button" class="relative h-6 w-11 shrink-0 rounded-full transition-colors" :class="entry.topic.isActive ? 'bg-brand-green' : 'bg-neutral-line'" :title="entry.topic.isActive ? 'Nonaktifkan topik' : 'Aktifkan topik'" :aria-label="entry.topic.isActive ? 'Nonaktifkan topik' : 'Aktifkan topik'" @click="ensureTopics();toggleTopic(entry.index)"><span class="absolute top-1 h-4 w-4 rounded-full bg-white shadow transition-transform" :class="entry.topic.isActive ? 'left-6' : 'left-1'" /></button><input :value="entry.topic.label" class="min-w-0 flex-1 rounded border px-2 py-1 text-sm" @focus="ensureTopics" @input="editTopic(entry.index,($event.target as HTMLInputElement).value)"/><button type="button" class="rounded p-1 text-neutral-charcoal/60 hover:bg-neutral-soft disabled:opacity-30" title="Naikkan urutan" aria-label="Naikkan urutan" :disabled="entry.index===0" @click="ensureTopics();moveTopic(entry.index,-1)"><ChevronUp class="h-4 w-4"/></button><button type="button" class="rounded p-1 text-neutral-charcoal/60 hover:bg-neutral-soft disabled:opacity-30" title="Turunkan urutan" aria-label="Turunkan urutan" :disabled="entry.index===topicRows.length-1" @click="ensureTopics();moveTopic(entry.index,1)"><ChevronDown class="h-4 w-4"/></button><button type="button" class="rounded p-1 text-red-700 hover:bg-red-50" title="Hapus topik" aria-label="Hapus topik" @click="ensureTopics();removeTopic(entry.index)"><Trash2 class="h-4 w-4"/></button></div><div v-if="topicPageCount>1" class="flex items-center justify-between gap-2 pt-2"><button type="button" class="rounded-full border px-3 py-1 text-xs disabled:opacity-40" :disabled="topicPageNumber===1" @click="setTopicPage(topicPageNumber-1)">Sebelumnya</button><span class="text-xs text-neutral-charcoal/50">{{topicPageNumber}} / {{topicPageCount}}</span><button type="button" class="rounded-full border px-3 py-1 text-xs disabled:opacity-40" :disabled="topicPageNumber===topicPageCount" @click="setTopicPage(topicPageNumber+1)">Berikutnya</button></div></div></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">2. Sorotan</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Editable · kurasi artikel yang muncul di section Sorotan.</p></div><span class="rounded-full bg-brand-green/10 px-3 py-1 text-[10px] font-semibold uppercase text-brand-green">Editable</span></div><button class="mt-3 text-xs text-red-700 underline" @click="resetSpotlight">Reset Sorotan ke Otomatis</button><div class="mt-5 grid gap-4 lg:grid-cols-[1fr_1fr]"><div class="rounded-xl border p-4"><p class="text-xs font-semibold uppercase tracking-wider text-neutral-charcoal/50">Featured</p><div class="mt-3 flex items-center gap-3"><span class="min-w-0 flex-1 truncate text-sm font-semibold">{{title(featured)}}</span><button class="rounded-full border px-3 py-1.5 text-xs" @click="picker='featured'">{{featured?'Ganti':'Pilih'}}</button></div></div><div class="rounded-xl border p-4"><p class="text-xs font-semibold uppercase tracking-wider text-neutral-charcoal/50">Supporting · maksimal 3</p><div v-for="(id,i) in supporting" :key="id" class="mt-2 flex items-center gap-2 text-sm"><span class="w-5 text-center text-xs">{{i+1}}</span><span class="min-w-0 flex-1 truncate">{{item(id)?.title}}</span><button class="text-xs" :disabled="i===0" @click="move('supporting',i,-1)">Naik</button><button class="text-xs" :disabled="i===supporting.length-1" @click="move('supporting',i,1)">Turun</button><button class="text-xs text-red-700" @click="remove('supporting',id)">×</button></div><button class="mt-3 rounded-full border px-3 py-1.5 text-xs" @click="picker='supporting'">Tambah supporting</button></div></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">3. Lagi Butuh Apa?</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Static · struktur dan konten dikelola langsung dari frontend.</p></div><span class="rounded-full bg-neutral-soft px-3 py-1 text-[10px] font-semibold uppercase">Static</span></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">4. Jelajahi Sudut Haramain</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Editable · artikel editorial pilihan, maksimal 6.</p></div><span class="rounded-full bg-brand-green/10 px-3 py-1 text-[10px] font-semibold uppercase text-brand-green">Editable</span></div><div class="mt-4 space-y-2"><div v-for="(id,i) in explore" :key="id" class="flex items-center gap-2 rounded-xl border p-3 text-sm"><span class="w-5 text-center text-xs">{{i+1}}</span><span class="min-w-0 flex-1 truncate">{{item(id)?.title}}</span><button class="text-xs" :disabled="i===0" @click="move('explore',i,-1)">Naik</button><button class="text-xs" :disabled="i===explore.length-1" @click="move('explore',i,1)">Turun</button><button class="text-xs text-red-700" @click="remove('explore',id)">×</button></div></div><button class="mt-3 rounded-full border px-3 py-1.5 text-xs" @click="picker='editorial'">Tambah editorial</button></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">5. Ada yang Bisa Kami Bantu?</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Static · struktur dan copy dikelola dari frontend.</p></div><span class="rounded-full bg-neutral-soft px-3 py-1 text-[10px] font-semibold uppercase">Static</span></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">6. Terbaru</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Dynamic · otomatis dari Article API berdasarkan priority dan publishedAt.</p></div><span class="rounded-full bg-neutral-soft px-3 py-1 text-[10px] font-semibold uppercase">Dynamic</span></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5 sm:p-6"><div class="flex items-center justify-between"><div><h2 class="font-heading text-lg font-semibold">7. Footer</h2><p class="mt-1 text-sm text-neutral-charcoal/55">Static · dikelola langsung dari frontend.</p></div><span class="rounded-full bg-neutral-soft px-3 py-1 text-[10px] font-semibold uppercase">Static</span></div></section><button class="mr-2 rounded-full border border-red-200 px-5 py-2.5 text-sm font-semibold text-red-700" @click="resetAllConfirm=true">Reset Semua ke Default</button><button class="rounded-full bg-brand-green px-5 py-2.5 text-sm font-semibold text-white" :disabled="saving" @click="save">{{saving?'Menyimpan...':'Simpan Perubahan'}}</button></div><div v-if="picker" class="fixed inset-0 z-50 flex items-center justify-center bg-neutral-charcoal/40 p-5" @click.self="picker=null"><section class="flex max-h-[80vh] w-full max-w-2xl flex-col rounded-2xl bg-white p-6 shadow-xl"><div class="flex items-center justify-between"><div><h2 class="font-heading text-xl font-semibold">Pilih Artikel Terbit</h2><p class="mt-1 text-xs text-neutral-charcoal/55">Hanya PUBLISHED dan tidak duplikat.</p></div><button class="text-2xl" @click="picker=null">×</button></div><input v-model="search" class="mt-4 rounded-xl border px-3 py-2 text-sm" placeholder="Cari judul..."/><div class="mt-4 min-h-0 space-y-2 overflow-y-auto"><button v-for="a in available" :key="a.id" :disabled="picker==='featured'?a.id===featured:pickList.includes(a.id)" class="flex w-full items-center gap-3 rounded-xl border p-3 text-left disabled:opacity-40" @click="picker==='featured'?(featured=a.id,mark(),picker=null):add(a.id)"><img v-if="a.heroImage" :src="a.heroImage" :alt="a.title" class="h-12 w-16 rounded-lg object-cover"/><span class="min-w-0 flex-1"><b class="block truncate text-sm">{{a.title}}</b><small class="text-neutral-charcoal/55">{{a.city}} · {{a.category}}</small></span><span class="text-xs font-semibold text-brand-green">Pilih</span></button></div></section></div><div v-if="resetAllConfirm" class="fixed inset-0 z-[60] flex items-center justify-center bg-neutral-charcoal/40 p-5"><div class="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl"><h2 class="font-heading text-lg font-semibold">Reset semua ke default?</h2><p class="mt-2 text-sm text-neutral-charcoal/65">Override Hero, Sorotan, dan Jelajahi akan dihapus setelah Anda menyimpan.</p><div class="mt-5 flex justify-end gap-2"><button class="rounded-full border px-4 py-2 text-sm" @click="resetAllConfirm=false">Batal</button><button class="rounded-full bg-red-700 px-4 py-2 text-sm text-white" @click="resetAll();resetAllConfirm=false">Reset</button></div></div></div><div v-if="preview" class="fixed inset-0 z-50 flex items-center justify-center bg-neutral-charcoal/50 p-4"><section class="flex max-h-[95vh] w-full max-w-6xl flex-col rounded-2xl bg-neutral-soft p-4 shadow-xl"><div class="flex items-center justify-between"><h2 class="font-heading text-lg font-semibold">Preview Home · draft belum disimpan</h2><div class="flex gap-2"><button class="rounded-full border px-3 py-1.5 text-xs" :class="device==='desktop'?'bg-brand-green text-white':''" @click="device='desktop'">Desktop</button><button class="rounded-full border px-3 py-1.5 text-xs" :class="device==='mobile'?'bg-brand-green text-white':''" @click="device='mobile'">Mobile</button><button class="text-2xl" @click="preview=false">×</button></div></div><div class="mt-4 min-h-0 overflow-auto rounded-xl bg-white p-6" :class="device==='mobile'?'mx-auto w-[390px] max-w-full':''"><div class="overflow-hidden rounded-2xl bg-brand-green text-white"><img v-if="hero.imageUrl" :src="hero.imageUrl" class="h-48 w-full object-cover opacity-70"/><div class="-mt-48 relative flex h-48 flex-col justify-end p-6"><h3 class="font-heading text-2xl font-bold">{{hero.headline||'Headline hero'}}</h3><p class="mt-2 text-sm opacity-80">{{hero.subheadline||'Subheadline hero'}}</p></div></div><h3 class="mt-8 font-heading text-2xl font-semibold">Topik Hero</h3><div class="mt-3 space-y-1 text-sm text-neutral-charcoal/70"><p v-for="topic in previewTopics" :key="topic">{{topic}}</p><p v-if="!previewTopics.length">Tidak ada topik aktif.</p></div><h3 class="mt-8 font-heading text-2xl font-semibold">Sorotan</h3><div class="mt-4 grid gap-3 sm:grid-cols-2"><div v-if="featured" class="rounded-xl border p-3"><img v-if="item(featured)?.heroImage" :src="item(featured).heroImage" class="h-32 w-full rounded-lg object-cover"/><b class="mt-2 block">{{item(featured)?.title}}</b></div><div class="space-y-2"><div v-for="id in supporting" :key="id" class="rounded-lg border p-2 text-sm">{{item(id)?.title}}</div></div></div><h3 class="mt-8 font-heading text-2xl font-semibold">Jelajahi Sudut Haramain</h3><div class="mt-3 grid gap-3 sm:grid-cols-3"><div v-for="id in explore" :key="id" class="rounded-lg border p-3 text-sm">{{item(id)?.title}}</div></div></div></section></div></div></template>
